function fits(node, pod) {
  return node.cpu >= pod.cpu && node.mem >= pod.mem;
}

function remainingAfter(node, pod) {
  return { cpu: node.cpu - pod.cpu, mem: node.mem - pod.mem };
}

function countFitting(nodes, pod) {
  return nodes.filter((n) => n.cpu >= pod.cpu && n.mem >= pod.mem).length;
}

function totalFreeCpu(nodes) {
  return nodes.reduce((sum, n) => sum + n.cpu, 0);
}

function pickNode(nodes, pod) {
  let best = null;
  for (const n of nodes) {
    if (n.cpu < pod.cpu || n.mem < pod.mem) continue;
    if (
      best === null ||
      n.cpu > best.cpu ||
      (n.cpu === best.cpu && n.mem > best.mem)
    ) {
      best = n;
    }
  }
  return best === null ? null : best.name;
}

function pendingCount(nodes, pods) {
  const free = nodes.map((n) => ({ cpu: n.cpu, mem: n.mem }));
  let pending = 0;
  for (const pod of pods) {
    let best = null;
    for (const n of free) {
      if (n.cpu < pod.cpu || n.mem < pod.mem) continue;
      if (
        best === null ||
        n.cpu > best.cpu ||
        (n.cpu === best.cpu && n.mem > best.mem)
      ) {
        best = n;
      }
    }
    if (best === null) {
      pending += 1;
    } else {
      best.cpu -= pod.cpu;
      best.mem -= pod.mem;
    }
  }
  return pending;
}

function pickNodePacked(nodes, pod) {
  let best = null;
  for (const n of nodes) {
    if (n.cpu < pod.cpu || n.mem < pod.mem) continue;
    if (
      best === null ||
      n.cpu < best.cpu ||
      (n.cpu === best.cpu && n.mem < best.mem)
    ) {
      best = n;
    }
  }
  return best === null ? null : best.name;
}
